from pathlib import Path
import re
from html import escape
root=Path(__file__).resolve().parents[1]
groups=[('languages','01 / SPEAK THE LANGUAGE','#22d3ee',[('python','Python'),('java','Java'),('typescript','TypeScript'),('javascript','JavaScript'),('cplusplus','C++'),('bash','Bash')]),('backend','02 / BUILD THE ENGINE','#a78bfa',[('fastapi','FastAPI'),('spring','Spring Boot'),('apachekafka','Kafka'),('postgresql','PostgreSQL'),('redis','Redis')]),('cloud','03 / SHIP TO THE CLOUD','#fb923c',[('amazonwebservices','AWS'),('kubernetes','Kubernetes'),('docker','Docker'),('terraform','Terraform'),('githubactions','Actions'),('linux','Linux')]),('frontend','04 / MAKE IT INTERACTIVE','#f472b6',[('react','React'),('nextjs','Next.js'),('tailwindcss','Tailwind'),('vitejs','Vite'),('html5','HTML'),('css3','CSS')]),('data','05 / FIND THE SIGNAL','#a3e635',[('numpy','NumPy'),('pandas','pandas'),('scikitlearn','scikit-learn'),('apachespark','Spark'),('postgresql','pgvector')]),('observability','06 / KEEP IT RUNNING','#fbbf24',[('prometheus','Prometheus'),('grafana','Grafana'),('git','Git'),('github','GitHub')])]
for filename,title,color,icons in groups:
 s=f'<svg xmlns="http://www.w3.org/2000/svg" width="1000" height="185" viewBox="0 0 1000 185" role="img" aria-label="{escape(title)}"><rect x="1" y="1" width="998" height="183" rx="20" fill="#0d1224" stroke="#28314c"/><rect x="26" y="25" width="5" height="17" rx="2" fill="{color}"/><text x="43" y="39" fill="{color}" font-family="Arial,sans-serif" font-size="14" font-weight="700" letter-spacing="2">{escape(title)}</text>'
 for i,(name,label) in enumerate(icons):
  x=28+i*160; svg=(root/'assets/toolkit/icons'/f'{name}.svg').read_text()
  svg=re.sub(r'<\?xml.*?\?>','',svg,flags=re.S)
  # Each brand gets an independent ID namespace when composed into the card.
  ids=re.findall(r'\bid=["\']([^"\']+)',svg)
  for ident in ids:
   svg=svg.replace(f'id="{ident}"',f'id="{name}-{ident}"').replace(f"id='{ident}'",f"id='{name}-{ident}'").replace(f'#{ident})',f'#{name}-{ident})').replace(f'"#{ident}"',f'"#{name}-{ident}"')
  svg=re.sub(r'<svg\b[^>]*>',lambda m:re.sub(r'\s(?:width|height|x|y)="[^"]*"','',m[0])[:-1]+f' x="{x+42}" y="65" width="52" height="52">',svg,count=1)
  if name in ['apachekafka','github','amazonwebservices','bash','pandas']:
   for dark in ['#000000','#000','#231f20','#181616','#252f3e','#232F3E','#130754','#092E20']:
    svg=svg.replace(dark,'#dbe6fc')
   svg=svg.replace('fill="black"','fill="#dbe6fc"')
  s+=f'<rect x="{x}" y="55" width="136" height="108" rx="14" fill="#172038"/>'+svg+f'<text x="{x+68}" y="146" text-anchor="middle" fill="#dbe6fc" font-family="Arial,sans-serif" font-size="13">{escape(label)}</text>'
 s+='</svg>'
 (root/'assets/toolkit'/f'{filename}.svg').write_text(s+'\n')
hero='''<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="420" viewBox="0 0 1200 420" role="img" aria-label="Rajashekar Reddy Akula — software engineer, cloud systems and applied AI"><defs><linearGradient id="g"><stop stop-color="#22d3ee"/><stop offset=".5" stop-color="#a78bfa"/><stop offset="1" stop-color="#fb7185"/></linearGradient><radialGradient id="glow"><stop stop-color="#6d28d9" stop-opacity=".5"/><stop offset="1" stop-color="#0a1020" stop-opacity="0"/></radialGradient><pattern id="grid" width="40" height="40" patternUnits="userSpaceOnUse"><path d="M40 0H0V40" fill="none" stroke="#27314e" stroke-opacity=".45"/></pattern></defs><rect width="1200" height="420" rx="24" fill="#0a1020"/><rect width="1200" height="420" rx="24" fill="url(#grid)"/><ellipse cx="900" cy="180" rx="390" ry="310" fill="url(#glow)"/><rect x="40" y="40" width="1120" height="340" rx="20" fill="none" stroke="#33415e"/><circle cx="68" cy="65" r="5" fill="#fb7185"/><circle cx="86" cy="65" r="5" fill="#fbbf24"/><circle cx="104" cy="65" r="5" fill="#a3e635"/><text x="128" y="70" font-family="monospace" font-size="13" fill="#9aaeca">rajashekar / build-with-intent</text><text x="70" y="139" fill="#22d3ee" font-family="Arial,sans-serif" font-size="13" letter-spacing="4" font-weight="700">SOFTWARE ENGINEERING × CLOUD × APPLIED AI</text><text x="66" y="207" fill="#f1f5ff" font-family="Arial,sans-serif" font-size="58" font-weight="800">Rajashekar Reddy Akula</text><text x="70" y="251" fill="url(#g)" font-family="Arial,sans-serif" font-size="25" font-weight="700">From an idea to a system people can use.</text><text x="70" y="293" fill="#a9b9d5" font-family="Arial,sans-serif" font-size="17">Distributed backends · Thoughtful interfaces · Data that drives decisions</text><rect x="70" y="325" width="135" height="27" rx="13" fill="#173846"/><text x="87" y="344" fill="#67e8f9" font-family="monospace" font-size="12">Buffalo, NY</text><rect x="220" y="325" width="234" height="27" rx="13" fill="#29224b"/><text x="238" y="344" fill="#c4b5fd" font-family="monospace" font-size="12">Building. Learning. Shipping.</text><rect x="40" y="378" width="1120" height="3" fill="url(#g)"/></svg>'''
(root/'assets/hero.svg').write_text(hero+'\n')
(root/'assets/footer.svg').write_text('''<svg xmlns="http://www.w3.org/2000/svg" width="1000" height="100" viewBox="0 0 1000 100"><defs><linearGradient id="g"><stop stop-color="#22d3ee"/><stop offset=".5" stop-color="#a78bfa"/><stop offset="1" stop-color="#fb7185"/></linearGradient></defs><rect width="1000" height="100" rx="20" fill="#0d1224"/><path d="M25 1H975" stroke="url(#g)" stroke-width="3"/><text x="500" y="49" text-anchor="middle" font-family="Arial,sans-serif" font-size="20" font-weight="700" fill="#e8edf7">Build with curiosity. Ship with intention.</text><text x="500" y="75" text-anchor="middle" font-family="monospace" font-size="12" fill="#9baac5">Thanks for stopping by — explore a project and say hello.</text></svg>\n''')
print('Created hero, footer, and six branded tool panels.')
